import { execFile } from "node:child_process";
import { writeFile } from "node:fs/promises";
import { fileURLToPath } from "node:url";

/** The most steps `pipe` and `flow` take, as their overloads in `index.ts` declare. */
const steps = 20;

const root = new URL("../../../", import.meta.url);
const header =
  "// Generated by generate-tests.ts. Run `node scripts/shared/pipe/generate-tests.ts` to update.";

function nested(depth: number): string {
  return `number${"[]".repeat(depth)}`;
}

// The type error lands on the first argument no overload can take, so the directive goes there.
function tooMany(call: string, last = "wrap"): string {
  return [
    `    ${call}(`,
    "      0,",
    ...Array<string>(last === "wrap" ? steps : steps + 1).fill("      wrap,"),
    "      // @ts-expect-error no overload takes this many steps",
    `      ${last},`,
    "    );",
  ].join("\n");
}

// The last step is async, so an overload whose result skips `Awaited` fails.
function chain(n: number): string {
  return lengths
    .slice(0, n)
    .map((i) => ((n - i) % 2 === 0 ? "wrapAsync" : "wrap"))
    .join(", ");
}

const lengths = Array.from({ length: steps }, (_, i) => i + 1);

// Every step changes the type, so an overload that wires a step to the wrong one fails.
const tests = `${header}
import { describe, expectTypeOf, test } from "vite-plus/test";

import { flow, pipe, type Sink } from "./index.ts";

const wrap = <T>(x: T): T[] => [x];
const wrapAsync = async <T>(x: T): Promise<T[]> => [x];

type Held<P> = { promise: P };
interface Holder extends Sink {
  readonly out: Held<this["in"]>;
}
const holder = { sink: (promise: unknown) => ({ promise }) } as unknown as Holder;

describe("pipe", () => {
  test("chains each step to the one before, at every length", () => {
${lengths
  .map(
    (n) =>
      `    expectTypeOf(pipe(0, ${Array(n).fill("wrap").join(", ")})).toEqualTypeOf<${nested(n)}>();`,
  )
  .join("\n")}
${tooMany("pipe")}
  });
});

describe("flow", () => {
  test("chains each step to the resolved one before, at every length", () => {
${lengths
  .map((n) => `    expectTypeOf(flow(0, ${chain(n)})).toEqualTypeOf<Promise<${nested(n)}>>();`)
  .join("\n")}
${tooMany("void flow")}
  });

  test("hands the chain's promise to a sink, at every length", () => {
${lengths
  .map(
    (n) =>
      `    expectTypeOf(flow(0, ${chain(n)}, holder)).toEqualTypeOf<{ promise: Promise<${nested(n)}> }>();`,
  )
  .join("\n")}
${tooMany("flow", "holder")}
  });
});
`;

function format(file: URL, text: string): Promise<string> {
  return new Promise((resolve, reject) => {
    const child = execFile(
      fileURLToPath(new URL("node_modules/.bin/vp", root)),
      ["fmt", `--stdin-filepath=${fileURLToPath(file)}`],
      { cwd: fileURLToPath(root) },
      (error, stdout) => (error ? reject(error) : resolve(stdout)),
    );
    child.stdin?.end(text);
  });
}

/** Where {@link generate} writes. */
const output = new URL("generated.test.ts", import.meta.url);

/** The type tests, one per overload, formatted. */
export function generate(): Promise<string> {
  return format(output, tests);
}

if (import.meta.main) {
  await writeFile(output, await generate());
}
